    /**
     * Tests creating a new DeviceVendor.
     *
     * @return    DeviceVendor
     */
    public DeviceVendor testCreate() throws Throwable {
    DeviceVendor entity = null;

    LOGGER.info( "DeviceVendorTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a DeviceVendor");

    StringBuilder msg = new StringBuilder( "-- Failed to create a DeviceVendor" );

    try {
        entity = service.createDeviceVendor( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getDeviceVendorId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a DeviceVendor with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

