    /**
     * Tests getting all DeviceVendors.
     *
     * @return    Collection
     */
    public List<DeviceVendor> testGetAll() throws Throwable {
    LOGGER.info( "DeviceVendorTest:testGetAll() - Retrieving Collection of DeviceVendors:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all DeviceVendor : " );
    List<DeviceVendor> collection  = null;

    try {
        // call the static get method on the DeviceVendorService
        collection = service.getAllDeviceVendor();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            DeviceVendor currEntity  = null;
            Iterator<DeviceVendor> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getDeviceVendorId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

